const items = $input.all();

function valor(obj, ...campos) {
  for (const campo of campos) {
    const v = obj[campo];

    if (v !== undefined && v !== null && v !== '') {
      if (typeof v === 'object') {
        return (
          v.name ??
          v.value ??
          v.start ??
          ''
        );
      }

      return v;
    }
  }

  return '';
}

// -----------------------------------------
// 1. Normalizar interacciones de Notion
// -----------------------------------------

const interacciones = items
  .map((item) => {
    const data = item.json;

    return {
      fecha: valor(
        data,
        'property_fecha',
        'Fecha',
        'fecha'
      ),

      direccion: String(
        valor(
          data,
          'property_direccion',
          'Dirección',
          'direccion'
        )
      ).trim(),

      mensaje: String(
        valor(
          data,
          'property_mensaje',
          'Mensaje',
          'mensaje'
        )
      ).trim(),

      // >>> NUEVO: leemos el campo "Códigos ofrecidos" creado en Notion
      codigos: String(
        valor(
          data,
          'property_códigos_ofrecidos',
          'Códigos ofrecidos',
          'codigos_ofrecidos'
        )
      ).trim(),
    };
  })
  .filter((item) => item.mensaje)
  .sort((a, b) => {
    const fechaA = new Date(a.fecha || 0).getTime();
    const fechaB = new Date(b.fecha || 0).getTime();

    return fechaA - fechaB;
  });

// -----------------------------------------
// 2. Construir memoria para la IA
// -----------------------------------------

const memoria = interacciones
  .map((item) => {
    const rol =
      item.direccion.toLowerCase() === 'saliente'
        ? 'ASISTENTE'
        : 'USUARIO';

    // >>> NUEVO: si hay códigos ofrecidos en ese turno, se anexan
    // entre corchetes al final de la línea. Esto NO lo ve el cliente
    // en Telegram, es solo información interna para el LLM de intención.
    const sufijoCodigos = item.codigos
      ? ` [Códigos ofrecidos: ${item.codigos}]`
      : '';

    return `${rol}: ${item.mensaje}${sufijoCodigos}`;
  })
  .join('\n');

// -----------------------------------------
// 3. Datos del mensaje actual
// -----------------------------------------

const normalizado =
  $('Normalizar mensaje').first().json;

// -----------------------------------------
// 4. Salida
// -----------------------------------------

return [
  {
    json: {
      telegram_chat_id:
        normalizado.telegram_chat_id ?? '',

      telegram_user_id:
        normalizado.telegram_user_id ?? '',

      mensaje_actual:
        normalizado.mensaje ?? '',

      memoria_conversacional:
        memoria,

      cantidad_interacciones:
        interacciones.length,

      caracteres_memoria:
        memoria.length
    }
  }
];

const raw = String($json.text ?? '').trim();

// ======================================================
// LIMPIEZA DE RESPUESTA DE GEMINI
// ======================================================

// Gemini debería devolver JSON puro, pero por seguridad
// eliminamos bloques Markdown si los agrega.
const limpio = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let analisis;

try {
  analisis = JSON.parse(limpio);
} catch (error) {
  throw new Error(
    `Gemini no devolvió un JSON válido: ${error.message}`
  );
}

// ======================================================
// VALORES PERMITIDOS
// ======================================================

const accionesPermitidas = [
  'consulta_general',
  'preguntar_dato',
  'buscar_propiedad',
  'crear_solicitud_visita',
  'cerrar_solicitud_visita',
  'cancelar_visita_existente',
  'derivar_humano'
];

const nivelesPermitidos = [
  'exploratorio',
  'interesado',
  'calificado'
];

const operacionesPermitidas = [
  'alquiler',
  'compra'
];

// Código interno de Gemini → valor exacto existente en Notion
const intencionesPermitidas = {
  saludo: 'Saludo',
  consulta_general: 'Consulta general',
  buscar_propiedad: 'Buscar propiedad',
  solicitar_informacion: 'Solicitar información',
  solicitar_visita: 'Solicitar visita',
  reprogramar_visita: 'Reprogramar visita',
  cancelar_visita: 'Cancelar visita',
  hablar_con_asesor: 'Hablar con asesor',
  otra: 'Otra'
};

// ======================================================
// VALIDACIÓN DE NEXT ACTION
// ======================================================

if (!accionesPermitidas.includes(analisis.next_action)) {
  throw new Error(
    `next_action inválido: ${analisis.next_action}`
  );
}

// ======================================================
// VALIDACIÓN DE NIVEL DE INTERÉS
// ======================================================

if (!nivelesPermitidos.includes(analisis.interest_level)) {
  throw new Error(
    `interest_level inválido: ${analisis.interest_level}`
  );
}

// ======================================================
// VALIDACIÓN DE OPERACIÓN
// ======================================================

if (
  analisis.operation !== null &&
  analisis.operation !== undefined &&
  !operacionesPermitidas.includes(analisis.operation)
) {
  throw new Error(
    `operation inválido: ${analisis.operation}`
  );
}

// ======================================================
// NORMALIZACIÓN DE INTENCIÓN
// ======================================================

const intentCode = String(
  analisis.intent ?? 'otra'
)
  .trim()
  .toLowerCase();

if (!intencionesPermitidas[intentCode]) {
  throw new Error(
    `intent inválido: ${analisis.intent}`
  );
}

const intentNotion =
  intencionesPermitidas[intentCode];

// ======================================================
// NORMALIZACIÓN DE PROPERTY CODES
// ======================================================

const propertyCodes = Array.isArray(analisis.property_codes)
  ? [
      ...new Set(
        analisis.property_codes
          .filter(Boolean)
          .map(codigo =>
            String(codigo)
              .trim()
              .toUpperCase()
          )
      )
    ]
  : [];

// ======================================================
// NORMALIZACIÓN DE MISSING FIELDS
// ======================================================

const missingFields = Array.isArray(analisis.missing_fields)
  ? [
      ...new Set(
        analisis.missing_fields
          .filter(Boolean)
          .map(campo =>
            String(campo).trim()
          )
      )
    ]
  : [];

// ======================================================
// NORMALIZACIÓN DE BOOLEANOS
// ======================================================

const requestedVisit =
  analisis.requested_visit === true;

const requiresHuman =
  analisis.requires_human === true;

// ======================================================
// VALIDACIONES DE CONSISTENCIA PARA VISITAS
// ======================================================

// ------------------------------------------------------
// CREAR SOLICITUD DE VISITA
// ------------------------------------------------------

// Para crear una visita debe existir al menos
// una propiedad identificada.
if (
  analisis.next_action === 'crear_solicitud_visita' &&
  propertyCodes.length === 0
) {
  throw new Error(
    'Gemini indicó crear_solicitud_visita pero no identificó ninguna propiedad.'
  );
}

// Si la acción es crear visita,
// requested_visit necesariamente debe ser true.
if (
  analisis.next_action === 'crear_solicitud_visita' &&
  requestedVisit !== true
) {
  throw new Error(
    'Gemini indicó crear_solicitud_visita pero requested_visit no es true.'
  );
}

// La intención correspondiente debe ser solicitar_visita.
if (
  analisis.next_action === 'crear_solicitud_visita' &&
  intentCode !== 'solicitar_visita'
) {
  throw new Error(
    `Gemini indicó crear_solicitud_visita pero intent es ${intentCode}.`
  );
}

// ------------------------------------------------------
// CERRAR SOLICITUD TODAVÍA NO CREADA
// ------------------------------------------------------

// cerrar_solicitud_visita representa el rechazo contextual
// antes de que exista una VIS en Notion.
if (
  analisis.next_action === 'cerrar_solicitud_visita' &&
  intentCode !== 'cancelar_visita'
) {
  throw new Error(
    `Gemini indicó cerrar_solicitud_visita pero intent es ${intentCode}.`
  );
}

if (
  analisis.next_action === 'cerrar_solicitud_visita' &&
  requestedVisit !== false
) {
  throw new Error(
    'Gemini indicó cerrar_solicitud_visita pero requested_visit no es false.'
  );
}

// ------------------------------------------------------
// CANCELAR VISITA YA EXISTENTE
// ------------------------------------------------------

// cancelar_visita_existente representa una VIS que
// ya fue creada previamente en Notion.
if (
  analisis.next_action === 'cancelar_visita_existente' &&
  intentCode !== 'cancelar_visita'
) {
  throw new Error(
    `Gemini indicó cancelar_visita_existente pero intent es ${intentCode}.`
  );
}

// Una cancelación nunca representa una nueva solicitud.
if (
  analisis.next_action === 'cancelar_visita_existente' &&
  requestedVisit !== false
) {
  throw new Error(
    'Gemini indicó cancelar_visita_existente pero requested_visit no es false.'
  );
}

// La cancelación automática no debe derivarse
// directamente a una persona.
if (
  analisis.next_action === 'cancelar_visita_existente' &&
  requiresHuman !== false
) {
  throw new Error(
    'Gemini indicó cancelar_visita_existente pero requires_human no es false.'
  );
}

// IMPORTANTE:
// NO exigimos property_codes para cancelar_visita_existente.
//
// Ejemplo válido:
// {
//   intent: "cancelar_visita",
//   property_codes: [],
//   next_action: "cancelar_visita_existente"
// }
//
// El flujo posterior buscará las VIS activas usando
// telegram_chat_id.

// ======================================================
// MEMORIA DEL MENSAJE
// ======================================================

const memoria =
  $('Construir memoria conversacional').first().json;

// ======================================================
// SALIDA NORMALIZADA
// ======================================================

return [
  {
    json: {

      telegram_chat_id:
        memoria.telegram_chat_id,

      telegram_user_id:
        memoria.telegram_user_id,

      mensaje_actual:
        memoria.mensaje_actual,

      // Código interno para lógica / auditoría.
      intent_code:
        intentCode,

      // Etiqueta normalizada para Notion.
      intent:
        intentNotion,

      operation:
        analisis.operation ?? null,

      zone:
        analisis.zone ?? null,

      property_type:
        analisis.property_type ?? null,

      bedrooms:
        analisis.bedrooms ?? null,

      budget_max:
        analisis.budget_max ?? null,

      property_codes:
        propertyCodes,

      interest_level:
        analisis.interest_level,

      requested_visit:
        requestedVisit,

      preferred_date:
        analisis.preferred_date ?? null,

      preferred_time:
        analisis.preferred_time ?? null,

      requires_human:
        requiresHuman,

      missing_fields:
        missingFields,

      next_action:
        analisis.next_action
    }
  }
];

const propiedades = $input.all();
const busqueda = $('Parsear análisis IA').first().json;

// -----------------------------
// Normalizar texto
// -----------------------------

function normalizar(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase();
}

// -----------------------------
// Datos buscados por el usuario
// -----------------------------

const operacionBuscada = normalizar(busqueda.operation);
const zonaBuscada = normalizar(busqueda.zone);
const tipoBuscado = normalizar(busqueda.property_type);

const dormitoriosBuscados =
  busqueda.bedrooms !== null &&
  busqueda.bedrooms !== undefined
    ? Number(busqueda.bedrooms)
    : null;

const presupuestoMax =
  busqueda.budget_max !== null &&
  busqueda.budget_max !== undefined
    ? Number(busqueda.budget_max)
    : null;

// -----------------------------
// Evaluar cada propiedad
// -----------------------------

const evaluadas = propiedades
  .map((item) => {
    const p = item.json;

    const operacion = normalizar(p.property_operación);
    const estado = normalizar(p.property_estado);
    const tipo = normalizar(p.property_tipo);
    const barrio = normalizar(p.property_barrio);

    const dormitorios =
      p.property_dormitorios !== null &&
      p.property_dormitorios !== undefined
        ? Number(p.property_dormitorios)
        : null;

    const precio =
      p.property_precio !== null &&
      p.property_precio !== undefined
        ? Number(p.property_precio)
        : null;

    // -----------------------------
    // Filtros obligatorios
    // -----------------------------
    // Solo Estado y Operación son excluyentes. El Tipo dejó de ser un
    // filtro obligatorio: ahora es un criterio de puntaje más (como
    // zona, dormitorios y presupuesto), para poder ofrecer alternativas
    // de otro tipo cuando no exista una coincidencia exacta.

    if (estado !== 'disponible') {
      return null;
    }

    if (
      operacionBuscada &&
      operacion !== operacionBuscada
    ) {
      return null;
    }

    // -----------------------------
    // Calcular coincidencia
    // -----------------------------

    let puntuacion = 0;
    const coincidencias = [];
    const diferencias = [];

    // Tipo
    if (tipoBuscado) {
      if (tipo === tipoBuscado) {
        puntuacion += 5;
        coincidencias.push('tipo');
      } else {
        diferencias.push('tipo');
      }
    }

    // Zona
    if (zonaBuscada) {
      if (barrio === zonaBuscada) {
        puntuacion += 4;
        coincidencias.push('zona');
      } else {
        diferencias.push('zona');
      }
    }

    // Dormitorios
    if (dormitoriosBuscados !== null) {
      if (dormitorios === dormitoriosBuscados) {
        puntuacion += 3;
        coincidencias.push('dormitorios');
      } else {
        diferencias.push('dormitorios');
      }
    }

    // Presupuesto
    let dentroPresupuesto = true;

    if (
      presupuestoMax !== null &&
      precio !== null
    ) {
      dentroPresupuesto =
        precio <= presupuestoMax;

      if (dentroPresupuesto) {
        puntuacion += 4;
        coincidencias.push('presupuesto');
      } else {
        diferencias.push('presupuesto');
      }
    }

    return {
      notion_page_id: p.id ?? '',
      codigo: p.property_código ?? '',
      propiedad:
        p.property_propiedad ??
        p.name ??
        '',
      operacion: p.property_operación ?? '',
      tipo: p.property_tipo ?? '',
      barrio: p.property_barrio ?? '',
      precio,
      moneda: p.property_moneda ?? '',
      dormitorios,
      baños: p.property_baños ?? null,
      superficie: p.property_superficie ?? null,
      expensas: p.property_expensas ?? null,
      direccion:
        p.property_dirección_pública ?? '',
      caracteristicas:
        p.property_características ?? '',
      requisitos:
        p.property_requisitos ?? '',
      dentro_presupuesto: dentroPresupuesto,
      puntuacion,
      coincidencias,
      diferencias
    };
  })
  .filter(Boolean)
  .sort((a, b) => b.puntuacion - a.puntuacion);

// Máximo 3 opciones para mostrar luego
const mejores = evaluadas.slice(0, 3);

return [
  {
    json: {
      telegram_chat_id:
        busqueda.telegram_chat_id,

      criterios_busqueda: {
        operation: busqueda.operation,
        zone: busqueda.zone,
        property_type: busqueda.property_type,
        bedrooms: busqueda.bedrooms,
        budget_max: busqueda.budget_max
      },

      cantidad_candidatas:
        evaluadas.length,

      cantidad_recomendadas:
        mejores.length,

      propiedades_recomendadas:
        mejores,

      hay_resultados:
        mejores.length > 0
    }
  }
];

const data = $input.first().json;

const propiedades = Array.isArray(data.propiedades_recomendadas)
  ? data.propiedades_recomendadas.slice(0, 3)
  : [];

if (propiedades.length === 0) {
  throw new Error(
    'No hay propiedades recomendadas para construir el contexto.'
  );
}

function formatearNumero(valor) {
  if (
    valor === null ||
    valor === undefined ||
    Number.isNaN(Number(valor))
  ) {
    return 'No informado';
  }

  return Number(valor).toLocaleString('es-AR');
}

const bloques = propiedades.map((p, index) => {

  const expensas =
    p.expensas !== null &&
    p.expensas !== undefined
      ? `${p.moneda || ''} ${formatearNumero(p.expensas)}`
      : 'No informadas';

  return [
    `<PROPIEDAD_${index + 1}>`,
    `Código: ${p.codigo || 'No informado'}`,
    `Propiedad: ${p.propiedad || 'No informado'}`,
    `Operación: ${p.operacion || 'No informado'}`,
    `Tipo: ${p.tipo || 'No informado'}`,
    `Barrio: ${p.barrio || 'No informado'}`,
    `Precio: ${p.moneda || ''} ${formatearNumero(p.precio)}`,
    `Dormitorios: ${p.dormitorios ?? 'No informado'}`,
    `Baños: ${p.baños ?? 'No informado'}`,
    `Superficie: ${
      p.superficie !== null && p.superficie !== undefined
        ? `${p.superficie} m²`
        : 'No informada'
    }`,
    `Expensas: ${expensas}`,
    `Dirección pública: ${p.direccion || 'No informada'}`,
    `Características: ${p.caracteristicas || 'No informadas'}`,
    `Requisitos: ${p.requisitos || 'No informados'}`,
    `Dentro del presupuesto: ${p.dentro_presupuesto ? 'Sí' : 'No'}`,
    `Coincidencias: ${
      Array.isArray(p.coincidencias)
        ? p.coincidencias.join(', ')
        : ''
    }`,
    `Diferencias: ${
      Array.isArray(p.diferencias) && p.diferencias.length > 0
        ? p.diferencias.join(', ')
        : 'Ninguna'
    }`,
    `</PROPIEDAD_${index + 1}>`
  ].join('\n');

});

const contextoPropiedades = bloques.join('\n\n');

return [
  {
    json: {
      telegram_chat_id: data.telegram_chat_id,

      criterios_busqueda:
        data.criterios_busqueda,

      cantidad_recomendadas:
        propiedades.length,

      contexto_propiedades:
        contextoPropiedades,

      propiedades_recomendadas:
        propiedades
    }
  }
];

