parameters.jsCode:
const data = $input.first().json;

const codigos = Array.isArray(data.property_codes)
  ? [...new Set(
      data.property_codes
        .filter(Boolean)
        .map(codigo => String(codigo).trim())
    )]
  : [];

if (codigos.length === 0) {
  throw new Error(
    'Se intentó crear una solicitud de visita sin propiedades identificadas.'
  );
}

return codigos.map((codigo, index) => ({
  json: {
    telegram_chat_id: data.telegram_chat_id,
    telegram_user_id: data.telegram_user_id,

    property_code: codigo,

    preferred_date: data.preferred_date ?? null,
    preferred_time: data.preferred_time ?? null,

    requested_visit: data.requested_visit === true,
    interest_level: data.interest_level,

    cantidad_propiedades_solicitadas: codigos.length,
    indice_propiedad: index + 1
  }
}));

const resultados = $input.all();

const solicitudes =
  $('Separar propiedades solicitadas').all();

const codigosSolicitados = [
  ...new Set(
    solicitudes
      .map(item =>
        String(item.json.property_code ?? '').trim()
      )
      .filter(Boolean)
  )
];

// =====================================================
// MAPEAR PROPIEDADES ENCONTRADAS
// =====================================================

const propiedadesEncontradas = resultados
  .map(item => item.json)
  .filter(p =>
    p.id &&
    p.property_código
  );

const mapaPropiedades = new Map();

for (const propiedad of propiedadesEncontradas) {

  const codigo = String(
    propiedad.property_código ?? ''
  ).trim();

  if (codigo) {
    mapaPropiedades.set(codigo, propiedad);
  }
}

// =====================================================
// CLASIFICAR DISPONIBILIDAD
// =====================================================

const propiedadesDisponibles = [];
const propiedadesNoDisponibles = [];
const codigosNoEncontrados = [];

for (const codigo of codigosSolicitados) {

  const propiedad =
    mapaPropiedades.get(codigo);

  // No existe en Notion
  if (!propiedad) {

    codigosNoEncontrados.push(codigo);

    continue;
  }

  const datosPropiedad = {
    notion_page_id:
      propiedad.id,

    codigo:
      propiedad.property_código ?? '',

    propiedad:
      propiedad.property_propiedad ??
      propiedad.name ??
      '',

    barrio:
      propiedad.property_barrio ?? '',

    direccion:
      propiedad.property_dirección_pública ?? '',

    precio:
      propiedad.property_precio ?? null,

    moneda:
      propiedad.property_moneda ?? '',

    estado:
      propiedad.property_estado ?? ''
  };

  const estado = String(
    propiedad.property_estado ?? ''
  )
    .trim()
    .toLowerCase();

  if (estado === 'disponible') {

    propiedadesDisponibles.push(
      datosPropiedad
    );

  } else {

    propiedadesNoDisponibles.push(
      datosPropiedad
    );
  }
}

// =====================================================
// DATOS GENERALES
// =====================================================

const analisis =
  $('Parsear análisis IA').first().json;

const cantidadDisponibles =
  propiedadesDisponibles.length;

const cantidadSolicitadas =
  codigosSolicitados.length;

return [
  {
    json: {

      telegram_chat_id:
        analisis.telegram_chat_id,

      telegram_user_id:
