  ? data.propiedades_disponibles
  : [];

if (!lead.id) {
  throw new Error(
    'No se encontró el Lead para crear las solicitudes de visita.'
  );
}

if (propiedades.length === 0) {
  throw new Error(
    'No hay propiedades disponibles para preparar solicitudes de visita.'
  );
}

return propiedades.map((propiedad, index) => ({
