const propertyId =
  Array.isArray(visita.property_propiedad)
    ? visita.property_propiedad[0]
    : null;

if (!propertyId) {
  throw new Error(
    `La visita ${visita.property_solicitud ?? visita.id} no tiene una propiedad relacionada.`
  );
}

if (!visita.property_telegram_chat_id) {
  throw new Error(
    `La visita ${visita.property_solicitud ?? visita.id} no tiene Telegram Chat ID.`
  );
}

return {
