    lead_page_id:
      Array.isArray(visita.property_lead)
        ? visita.property_lead[0] ?? null
        : null,

    property_page_id:
      propertyId,

    property_url:
      'https://www.notion.so/' +
      propertyId.replace(/-/g, ''),

    estado_visita:
      visita.property_estado,

    cliente_notificado:
      visita.property_cliente_notificado,

    observaciones:
      visita.property_observaciones ?? ''
  }
};

const propiedades = $input.all().map(item => item.json);

const visitas = $('Preparar visita rechazada')
  .all()
  .map(item => item.json);

// Mapa: ID de página VIS -> datos de la visita
const visitasPorId = new Map();

for (const visita of visitas) {
  visitasPorId.set(visita.visit_page_id, visita);
}

const grupos = new Map();

for (const propiedad of propiedades) {

  // La propiedad trae la relación con la VIS correspondiente
  const idsVisitas = Array.isArray(propiedad.property_visitas)
    ? propiedad.property_visitas
    : [];

  const visitId = idsVisitas.find(id =>
    visitasPorId.has(id)
  );

  if (!visitId) {
    throw new Error(
      `No se pudo relacionar la propiedad ${propiedad.name ?? propiedad.id} con una visita rechazada.`
    );
  }

  const visita = visitasPorId.get(visitId);

  const chatId = String(
    visita.telegram_chat_id ?? ''
  ).trim();

  if (!chatId) {
    throw new Error(
      `La visita ${visita.solicitud ?? visitId} no tiene telegram_chat_id.`
    );
  }

  if (!grupos.has(chatId)) {
    grupos.set(chatId, {
      telegram_chat_id: chatId,
      lead_page_id: visita.lead_page_id ?? null,
      visitas: []
    });
  }

  grupos.get(chatId).visitas.push({
    visit_page_id: visita.visit_page_id,
    solicitud: visita.solicitud,

    property_page_id: propiedad.id,

    property_code:
      propiedad.property_código ?? '',

    property_name:
      propiedad.property_propiedad ??
      propiedad.name ??
      'Propiedad',

    property_barrio:
      propiedad.property_barrio ?? ''
  });
}

// Un item de salida por cliente
return Array.from(grupos.values()).map(grupo => {

  const cantidad = grupo.visitas.length;

  const detalle = grupo.visitas
    .map(v => {
      const barrio = v.property_barrio
        ? ` (${v.property_barrio})`
        : '';

      return `• ${v.property_name}${barrio}`;
    })
    .join('\n');

  const mensaje =
    cantidad === 1
      ? `Te actualizo tu solicitud de visita.\n\n` +
        `En esta oportunidad, la inmobiliaria no puede avanzar con la visita para:\n\n` +
        `${detalle}\n\n` +
        `Si querés, puedo ayudarte a buscar otras opciones disponibles que se ajusten a lo que estás buscando.`

      : `Te actualizo tus solicitudes de visita.\n\n` +
        `En esta oportunidad, la inmobiliaria no puede avanzar con las visitas para las siguientes propiedades:\n\n` +
        `${detalle}\n\n` +
        `Si querés, puedo ayudarte a buscar otras opciones disponibles que se ajusten a lo que estás buscando.`;

  return {
    json: {
      telegram_chat_id: grupo.telegram_chat_id,
      lead_page_id: grupo.lead_page_id,

      visit_page_ids:
        grupo.visitas.map(v => v.visit_page_id),

      solicitudes:
        grupo.visitas.map(v => v.solicitud),

      property_codes:
        grupo.visitas.map(v => v.property_code),

      cantidad_rechazadas: cantidad,

      mensaje
    }
  };
});

const grupos = $('Preparar aviso de rechazo')
  .all()
  .map(item => item.json);

const resultado = [];

for (const grupo of grupos) {
  const visitIds = Array.isArray(grupo.visit_page_ids)
    ? grupo.visit_page_ids
    : [];

  const solicitudes = Array.isArray(grupo.solicitudes)
    ? grupo.solicitudes
    : [];

  for (let i = 0; i < visitIds.length; i++) {
