        : null,

    property_page_id:
      Array.isArray(visita.property_propiedad)
        ? visita.property_propiedad[0] ?? null
        : null,

    fecha_solicitud:
      visita.property_fecha_solicitud?.start ?? null
  }));

// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      telegram_chat_id:
        String(analisis.telegram_chat_id ?? ''),

      lead_page_id:
        visitasActivas[0]?.lead_page_id ??
        (Array.isArray(visitas[0]?.property_lead)
          ? visitas[0].property_lead[0] ?? null
          : null),

      property_codes_solicitados:
        Array.isArray(analisis.property_codes)
          ? analisis.property_codes
          : [],

      cantidad_registros_recibidos:
        entradas.length,

      cantidad_visitas_unicas:
        visitas.length,

      cantidad_visitas_activas:
        visitasActivas.length,

      hay_visitas_activas:
        visitasActivas.length > 0,

      visitas_activas:
        visitasActivas
    }
  }
];

const data = $json;

return [
  {
    json: {
      telegram_chat_id:
        String(data.telegram_chat_id ?? ''),

      lead_page_id:
        data.lead_page_id ?? null,

      mensaje:
        'ℹ️ No encontré ninguna visita activa para cancelar en este momento.\n\n' +
        'Si querés, puedo ayudarte a buscar otras propiedades o gestionar una nueva solicitud de visita.',

      intent:
        'Cancelar visita',

      intent_code:
        'cancelar_visita'
    }
  }
];

const propiedades = $input.all().map(item => item.json);

const visitas = $('Separar visitas para identificar cancelación')
  .all()
  .map(item => item.json);

// ======================================================
// MAPA DE PROPIEDADES POR ID DE NOTION
// ======================================================

const propiedadesPorId = new Map();

for (const propiedad of propiedades) {
  if (!propiedad.id) continue;

  propiedadesPorId.set(
    propiedad.id,
    propiedad
  );
}

// ======================================================
// CRUZAR CADA VISITA CON SU PROPIEDAD
// ======================================================

const resultado = [];

for (const visita of visitas) {

  const propiedad =
    propiedadesPorId.get(visita.property_page_id);

  if (!propiedad) {
    throw new Error(
      `No se encontró la propiedad relacionada con ${visita.solicitud}. ID: ${visita.property_page_id}`
    );
  }

  resultado.push({
    json: {
      visit_page_id:
        visita.visit_page_id,

      visit_page_url:
        visita.visit_page_url,

      solicitud:
        visita.solicitud,

      estado_visita:
        visita.estado,

      telegram_chat_id:
        visita.telegram_chat_id,

      lead_page_id:
        visita.lead_page_id,

      property_page_id:
        propiedad.id,

      property_code:
        propiedad.property_código ?? '',

      property_name:
        propiedad.property_propiedad ??
        propiedad.name ??
        'Propiedad',

      property_barrio:
        propiedad.property_barrio ?? '',

      property_estado:
        propiedad.property_estado ?? '',

      property_codes_solicitados:
        visita.property_codes_solicitados ?? [],

      cantidad_visitas_activas:
        visita.cantidad_visitas_activas
    }
  });
}

return resultado;

const data = $input.first().json;

const visitas = Array.isArray(data.visitas_activas)
  ? data.visitas_activas
  : [];

return visitas.map(visita => {
  if (!visita.property_page_id) {
    throw new Error(
      `La visita ${visita.solicitud ?? visita.visit_page_id} no tiene propiedad relacionada.`
    );
  }

  return {
    json: {
      visit_page_id: visita.visit_page_id,
      visit_page_url: visita.visit_page_url,

      solicitud: visita.solicitud,
      estado: visita.estado,

      telegram_chat_id: visita.telegram_chat_id,
      lead_page_id: visita.lead_page_id,

      property_page_id: visita.property_page_id,

      property_url:
        'https://www.notion.so/' +
        visita.property_page_id.replace(/-/g, ''),

      property_codes_solicitados:
        data.property_codes_solicitados ?? [],

      cantidad_visitas_activas:
        data.cantidad_visitas_activas
    }
  };
});

const data = $input.first().json;

// =====================================================
// VISITAS ACTIVAS DISPONIBLES PARA SELECCIONAR
// =====================================================

const visitas = Array.isArray(data.visitas_disponibles)
  ? data.visitas_disponibles
  : [];

if (visitas.length === 0) {
  throw new Error(
    'No hay visitas disponibles para solicitar una selección.'
  );
}

// =====================================================
// DATOS GENERALES
// =====================================================

const telegramChatId =
  String(data.telegram_chat_id ?? '').trim();

const leadPageId =
  data.lead_page_id ?? null;

if (!telegramChatId) {
  throw new Error(
    'No se encontró Telegram Chat ID para solicitar la selección.'
  );
}

// =====================================================
// DETALLE VISIBLE PARA EL CLIENTE
// =====================================================

const detalle = visitas
  .map((visita, index) => {

    const numero =
      index === 0 ? '1️⃣' :
      index === 1 ? '2️⃣' :
      index === 2 ? '3️⃣' :
      `${index + 1}.`;

    const nombre =
      visita.property_name ||
      'Propiedad';

    const barrio =
      visita.property_barrio
        ? ` — ${visita.property_barrio}`
        : '';

    return `${numero} ${nombre}${barrio}`;
  })
  .join('\n');

// =====================================================
// MENSAJE
// =====================================================

const mensaje =
  `📅 Encontré ${visitas.length} ${
    visitas.length === 1
      ? 'visita activa'
      : 'visitas activas'
  }.\n\n` +

  `¿Cuál querés cancelar?\n\n` +

  `${detalle}\n\n` +

  `Podés indicarme, por ejemplo, “la de General Paz”, ` +
  `“la primera” o “las dos”.`;

// =====================================================
// CÓDIGOS PARA MEMORIA CONVERSACIONAL
// =====================================================

const propertyCodes = visitas
  .map(visita => visita.property_code)
  .filter(Boolean);

// =====================================================
// SALIDA
// =====================================================

return [
  {
    json: {
      telegram_chat_id: telegramChatId,
      lead_page_id: leadPageId,

      cantidad_visitas: visitas.length,

      visit_page_ids:
        visitas
          .map(v => v.visit_page_id)
          .filter(Boolean),

      solicitudes:
        visitas
          .map(v => v.solicitud)
          .filter(Boolean),

      property_codes:
        propertyCodes,

      visitas: visitas.map(visita => ({
        visit_page_id:
          visita.visit_page_id,

        solicitud:
          visita.solicitud,

        property_code:
          visita.property_code,

        property_name:
          visita.property_name,

        property_barrio:
          visita.property_barrio
      })),

      mensaje
    }
  }
];

