parameters.jsCode:
const entradas = $input.all().map(item => item.json);

// ======================================================
// ELIMINAR POSIBLES DUPLICADOS POR VISIT ID
// ======================================================

const visitasMap = new Map();

for (const visita of entradas) {
  if (!visita.visit_page_id) continue;

  if (!visitasMap.has(visita.visit_page_id)) {
    visitasMap.set(visita.visit_page_id, visita);
  }
}

const visitas = Array.from(visitasMap.values());

if (visitas.length === 0) {
  throw new Error(
    'No se recibieron visitas activas para resolver la cancelación.'
  );
}

// ======================================================
// DATOS GENERALES
// ======================================================

const telegramChatId =
  String(visitas[0].telegram_chat_id ?? '');

const leadPageId =
  visitas[0].lead_page_id ?? null;

// Los códigos elegidos por el cliente vienen del análisis IA.
const propertyCodesSolicitados = [
  ...new Set(
    visitas
      .flatMap(visita =>
        Array.isArray(visita.property_codes_solicitados)
          ? visita.property_codes_solicitados
          : []
      )
      .filter(Boolean)
      .map(codigo =>
        String(codigo).trim().toUpperCase()
      )
  )
];

// ======================================================
// CÓDIGOS DE VISITAS ACTIVAS
// ======================================================

const codigosActivos = new Set(
  visitas
    .map(visita => visita.property_code)
    .filter(Boolean)
    .map(codigo =>
      String(codigo).trim().toUpperCase()
    )
);

// ======================================================
// RESOLVER CUÁLES CANCELAR
// ======================================================

let visitasACancelar = [];
let requiereSeleccion = false;
let motivoSeleccion = null;

// ------------------------------------------------------
// CASO 1:
// El usuario identificó una o más propiedades.
// Ej:
// "la primera"
// "la de General Paz"
// "las dos"
// ------------------------------------------------------

if (propertyCodesSolicitados.length > 0) {

  visitasACancelar = visitas.filter(visita => {

    const codigo =
      String(visita.property_code ?? '')
        .trim()
        .toUpperCase();

    return propertyCodesSolicitados.includes(codigo);
  });

  // Gemini identificó códigos pero ninguno corresponde
  // actualmente a una visita activa.
  if (visitasACancelar.length === 0) {
    requiereSeleccion = true;
    motivoSeleccion = 'propiedad_no_coincide_con_visita_activa';
  }

}

// ------------------------------------------------------
// CASO 2:
// No identificó propiedad pero existe UNA SOLA visita.
// Se puede cancelar directamente.
// ------------------------------------------------------

else if (visitas.length === 1) {

  visitasACancelar = [visitas[0]];

}

// ------------------------------------------------------
// CASO 3:
// Existen varias visitas activas y no sabemos cuál.
// Debemos preguntarle.
// ------------------------------------------------------

else {

  requiereSeleccion = true;
  motivoSeleccion = 'multiples_visitas_sin_seleccion';

}

// ======================================================
// CÓDIGOS SOLICITADOS QUE YA NO SON VISITAS ACTIVAS
// ======================================================

const codigosNoActivos =
  propertyCodesSolicitados.filter(
    codigo => !codigosActivos.has(codigo)
  );

// ======================================================
// VISITAS QUE QUEDARÁN ACTIVAS
// ======================================================

const idsACancelar = new Set(
  visitasACancelar.map(v => v.visit_page_id)
);

const visitasRestantes = visitas.filter(
  visita => !idsACancelar.has(visita.visit_page_id)
);

// ======================================================
// TIPO DE CANCELACIÓN
// ======================================================

let tipoCancelacion = null;

if (
  !requiereSeleccion &&
  visitasACancelar.length > 0
) {

  tipoCancelacion =
    visitasRestantes.length === 0
      ? 'total'
      : 'parcial';
}

// ======================================================
// NORMALIZAR VISITA
// ======================================================

const normalizarVisita = visita => ({
  visit_page_id:
    visita.visit_page_id,

  visit_page_url:
    visita.visit_page_url,

  solicitud:
    visita.solicitud,

  estado_visita:
    visita.estado_visita,

  property_page_id:
    visita.property_page_id,

  property_code:
    visita.property_code,

  property_name:
    visita.property_name,

  property_barrio:
    visita.property_barrio
});

// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {

      telegram_chat_id:
        telegramChatId,

      lead_page_id:
        leadPageId,

      cantidad_visitas_activas:
        visitas.length,

      property_codes_solicitados:
        propertyCodesSolicitados,

      codigos_no_activos:
        codigosNoActivos,

      requiere_seleccion:
        requiereSeleccion,

      motivo_seleccion:
        motivoSeleccion,

      cantidad_a_cancelar:
        visitasACancelar.length,

      cantidad_restantes:
        visitasRestantes.length,

      tipo_cancelacion:
        tipoCancelacion,

      visitas_a_cancelar:
        visitasACancelar.map(normalizarVisita),

      visitas_restantes:
        visitasRestantes.map(normalizarVisita),

      visitas_disponibles:
        visitas.map(normalizarVisita)
    }
  }
];

const data = $input.first().json;

const visitasACancelar = Array.isArray(data.visitas_a_cancelar)
  ? data.visitas_a_cancelar
  : [];

if (visitasACancelar.length === 0) {
  throw new Error(
    'Resolver visitas a cancelar no devolvió ninguna visita para cancelar.'
  );
}

return visitasACancelar.map(visita => ({
  json: {
    // ==================================================
    // VISITA A CANCELAR
    // ==================================================

    visit_page_id:
      visita.visit_page_id,

    visit_page_url:
      visita.visit_page_url,

    solicitud:
      visita.solicitud,

    estado_anterior:
      visita.estado_visita,

    property_page_id:
      visita.property_page_id,

    property_code:
      visita.property_code,

    property_name:
      visita.property_name,

    property_barrio:
      visita.property_barrio,

    // ==================================================
    // CLIENTE
    // ==================================================

    telegram_chat_id:
      data.telegram_chat_id,

    lead_page_id:
      data.lead_page_id,

    // ==================================================
    // RESULTADO GENERAL DE LA CANCELACIÓN
    // ==================================================

    tipo_cancelacion:
      data.tipo_cancelacion,

    cantidad_visitas_activas:
      data.cantidad_visitas_activas,

    cantidad_a_cancelar:
      data.cantidad_a_cancelar,

    cantidad_restantes:
      data.cantidad_restantes,

    // Conservamos las restantes para el mensaje posterior.
    visitas_restantes:
      data.visitas_restantes ?? [],

    // Estado que vamos a persistir.
    nuevo_estado:
      'Cancelada'
  }
}));

const canceladas = $('Separar visitas a cancelar')
  .all()
  .map(item => item.json);

if (canceladas.length === 0) {
  throw new Error(
    'No se encontraron visitas canceladas para preparar la comunicación.'
  );
}

const primera = canceladas[0];

const tipoCancelacion =
  primera.tipo_cancelacion;

const telegramChatId =
  String(primera.telegram_chat_id ?? '');

const leadPageId =
  primera.lead_page_id ?? null;

const cantidadActivasAntes =
  primera.cantidad_visitas_activas ?? canceladas.length;

const cantidadCanceladas =
  canceladas.length;

const visitasRestantes =
  Array.isArray(primera.visitas_restantes)
    ? primera.visitas_restantes
    : [];

// ======================================================
// DETALLE DE VISITAS CANCELADAS
// ======================================================

const detalleCanceladas = canceladas
  .map(visita => {
    const barrio = visita.property_barrio
      ? ` — ${visita.property_barrio}`
      : '';

    return `❌ ${visita.property_name}${barrio}`;
  })
  .join('\n');

// ======================================================
// DETALLE DE VISITAS QUE SIGUEN ACTIVAS
// ======================================================

const detalleRestantes = visitasRestantes
  .map(visita => {
    const barrio = visita.property_barrio
      ? ` — ${visita.property_barrio}`
      : '';

    return `✅ ${visita.property_name}${barrio}`;
  })
  .join('\n');

// ======================================================
// MENSAJE PARA EL CLIENTE
// ======================================================

let mensajeCliente;

if (tipoCancelacion === 'total') {

  mensajeCliente =
    `✅ Listo, cancelé ${
      cantidadCanceladas === 1
        ? 'tu solicitud de visita'
        : 'tus solicitudes de visita'
    }.\n\n` +
    `${detalleCanceladas}\n\n` +
    `Ya no tenés visitas activas en este momento.\n\n` +
    `🏠 Si querés, puedo ayudarte a buscar otras propiedades.`;

} else {

  mensajeCliente =
    `✅ Listo, cancelé ${
      cantidadCanceladas === 1
        ? 'esta solicitud de visita'
        : 'estas solicitudes de visita'
    }:\n\n` +
    `${detalleCanceladas}\n\n` +
    `📅 ${
      visitasRestantes.length === 1
        ? 'Esta visita continúa activa:'
        : 'Estas visitas continúan activas:'
    }\n\n` +
    `${detalleRestantes}`;
}

// ======================================================
// MENSAJE PARA SLACK
// ======================================================

let mensajeSlack;

if (tipoCancelacion === 'total') {

  mensajeSlack =
    `🚫 *Cancelación total de visitas*\n\n` +
    `💬 *Telegram Chat ID:* ${telegramChatId}\n` +
    `📊 *Visitas activas antes:* ${cantidadActivasAntes}\n` +
    `❌ *Canceladas por el cliente:* ${cantidadCanceladas}\n\n` +
    `*Visitas canceladas:*\n${detalleCanceladas}\n\n` +
    `El cliente ya no tiene solicitudes de visita activas.`;

} else {

  mensajeSlack =
    `⚠️ *Cancelación parcial de visitas*\n\n` +
    `💬 *Telegram Chat ID:* ${telegramChatId}\n` +
    `📊 *Visitas activas antes:* ${cantidadActivasAntes}\n` +
    `❌ *Canceladas por el cliente:* ${cantidadCanceladas}\n` +
    `✅ *Continúan activas:* ${visitasRestantes.length}\n\n` +
    `*Canceladas:*\n${detalleCanceladas}\n\n` +
    `*Continúan activas:*\n${detalleRestantes}`;
}

// ======================================================
// SALIDA
// ======================================================

return [
  {
    json: {
      telegram_chat_id: telegramChatId,
      lead_page_id: leadPageId,

      tipo_cancelacion: tipoCancelacion,

      cantidad_activas_antes:
        cantidadActivasAntes,

      cantidad_canceladas:
        cantidadCanceladas,

      cantidad_restantes:
        visitasRestantes.length,

      property_codes_cancelados:
        canceladas.map(v => v.property_code),

      visit_page_ids_cancelados:
        canceladas.map(v => v.visit_page_id),

      mensaje_cliente:
        mensajeCliente,

      mensaje_slack:
        mensajeSlack
    }
  }
];

