const items = $input.all().map(item => item.json);

if (items.length === 0) {
  throw new Error('No hay confirmaciones para consolidar.');
}

const grupos = new Map();

for (const item of items) {

  const chatId = String(
    item.telegram_chat_id ?? ''
  ).trim();

  if (!chatId) {
    throw new Error(
      'Una confirmación no tiene Telegram Chat ID.'
    );
  }

  if (!grupos.has(chatId)) {
    grupos.set(chatId, {
      telegram_chat_id: chatId,
      lead_page_id: item.lead_page_id ?? '',
      visitas: []
    });
  }

  grupos.get(chatId).visitas.push({
    visit_page_id: item.visit_page_id,
    visit_url: item.visit_url,
    solicitud: item.solicitud,

    property_page_id: item.property_page_id,
    property_code: item.property_code,
    property_name: item.property_name,
    property_barrio: item.property_barrio,
    property_direccion: item.property_direccion,

    fecha_confirmacion: item.fecha_confirmacion
  });
}

return Array.from(grupos.values()).map(grupo => {

  const visitas = grupo.visitas;

  let mensaje;

  if (visitas.length === 1) {

    const v = visitas[0];

    mensaje =
      `✅ La inmobiliaria confirmó tu solicitud de visita para ` +
      `${v.property_name}` +
      (v.property_barrio
        ? ` (${v.property_barrio})`
        : '') +
      `.\n\n` +
      `Un miembro del equipo se va a comunicar con vos para coordinar el día y horario de la visita.\n\n` +
      `La fecha y el horario todavía no están definidos.`;

  } else {

    const detalle = visitas
      .map((v, i) =>
        `${i + 1}. ${v.property_name}` +
        (v.property_barrio
          ? ` (${v.property_barrio})`
          : '')
      )
      .join('\n');

    mensaje =
      `✅ La inmobiliaria confirmó tus solicitudes de visita para estas propiedades:\n\n` +
      `${detalle}\n\n` +
      `Un miembro del equipo se va a comunicar con vos para coordinar el día y horario de las visitas.\n\n` +
      `La fecha y el horario todavía no están definidos.`;
  }

  return {
    json: {
      telegram_chat_id: grupo.telegram_chat_id,
      lead_page_id: grupo.lead_page_id,

      cantidad_visitas: visitas.length,

      visitas,

      property_codes: visitas
        .map(v => v.property_code)
        .filter(Boolean),

      mensaje
    }
  };
});

const grupos =
  $('Consolidar confirmaciones por cliente')
    .all()
    .map(item => item.json);

if (grupos.length === 0) {
  throw new Error(
    'No hay grupos de visitas confirmadas para separar.'
  );
}

const salida = [];

for (const grupo of grupos) {

  const visitas = Array.isArray(grupo.visitas)
    ? grupo.visitas
    : [];

  for (const visita of visitas) {

    if (!visita.visit_page_id && !visita.visit_url) {
      throw new Error(
        'Una visita confirmada no tiene ID ni URL de Notion.'
      );
    }

    salida.push({
      json: {
        visit_page_id:
          visita.visit_page_id ?? '',

        visit_url:
          visita.visit_url ?? '',

        solicitud:
          visita.solicitud ?? '',

        property_page_id:
          visita.property_page_id ?? '',

        property_code:
          visita.property_code ?? '',

        property_name:
          visita.property_name ?? '',

        property_barrio:
          visita.property_barrio ?? '',

        telegram_chat_id:
          grupo.telegram_chat_id ?? '',

        lead_page_id:
          grupo.lead_page_id ?? '',

        fecha_confirmacion:
          visita.fecha_confirmacion ??
          new Date().toISOString(),

        nuevo_estado:
          'Confirmada'
      }
    });
  }
}

return salida;

