const errorData = $input.first().json;

// Datos del mensaje original
const memoria = $('Construir memoria conversacional').first().json;

const telegramChatId = String(
  memoria.telegram_chat_id ??
  memoria.telegram_user_id ??
  ''
);

const mensajeUsuario = String(
  memoria.mensaje_actual ??
  ''
).trim();

// El formato exacto del error puede variar según el nodo,
// así que intentamos recuperar los campos más comunes.
const mensajeError = String(
  errorData.error?.message ??
  errorData.error ??
  errorData.message ??
  errorData.description ??
  'Error desconocido al procesar la solicitud con Gemini.'
);

const tipoError = String(
  errorData.error?.name ??
  errorData.name ??
  'Gemini/API Error'
);

return [
  {
    json: {
      telegram_chat_id: telegramChatId,

      mensaje_usuario: mensajeUsuario,

      origen_error: 'Gemini',

      nodo_error: 'Analizar intención',

      tipo_error: tipoError,

      mensaje_error: mensajeError,

      fecha_error: new Date().toISOString(),

      estado: 'Error',

      mensaje_cliente:
        'Tuvimos un inconveniente al procesar tu mensaje. Por favor, intentá nuevamente en unos minutos.'
    }
  }
];

propertyValues.textContent:
={{
  'Origen: ' + $('Preparar error Gemini1').first().json.origen_error +
  '\nTipo técnico: ' + $('Preparar error Gemini1').first().json.tipo_error +
  '\nMensaje del usuario: ' + $('Preparar error Gemini1').first().json.mensaje_usuario
}}
